  // 프로젝트 자동 생성 포스트 (스텁)
  const projectPosts = [];
  const categories = ['Core', 'Modules', 'Archived', 'Tools', 'Experiments'];
  const projects = [
    'freelang-mobile', 'freelang-compiler', 'freelang-runtime',
    'freelang-backend-system', 'freelang-final', 'freelang-stdlib',
    'ai-accelerator-compiler', 'clarity-lang', 'freelang-jit-compiler',
    'pyfree', 'freelang-v2', 'freelang-c-final'
  ];

  // 프로젝트당 10개 포스트 생성
  const postTemplates = [
    '프로젝트 개요 & 역사',
    '아키텍처 & 설계',
    '구현 상세 - Part 1',
    '구현 상세 - Part 2',
    '테스트 & 검증',
    '성능 벤치마크',
    '실제 사용 사례',
    '확장성 & 미래',
    '비교 분석',
    '심화 토픽 & 연구'
  ];

  projects.forEach(project => {
    postTemplates.forEach((template, idx) => {
      projectPosts.push({
        title: `[${project}] ${idx + 1}. ${template}`,
        content: `<p><strong>${project}</strong> 프로젝트의 ${template} 포스트입니다.</p><p>상세 내용은 GitHub를 참고해주세요.</p>`,
        labels: [project, 'Project', 'AutoGenerated']
      });
    });
  });

  const allPosts = [...serverPosts, ...projectPosts];
  console.log(`📊 총 ${allPosts.length}개 포스트 발행 예정\n`);

  const results = [];
  let successCount = 0;
  let errorCount = 0;

  for (let i = 0; i < allPosts.length; i++) {
    const post = allPosts[i];
    console.log(`[${i + 1}/${allPosts.length}] 📝 ${post.title.substring(0, 50)}...`);

    const result = await publishPost(blogger, post);

    if (result.success) {
      console.log(`  ✅ 발행 완료`);
      successCount++;
      results.push({
        title: post.title,
        status: 'success',
        url: result.url,
        timestamp: new Date().toISOString()
      });
    } else {
      console.log(`  ❌ 실패: ${result.error}`);
      errorCount++;
      results.push({
        title: post.title,
        status: 'error',
        error: result.error,
        timestamp: new Date().toISOString()
      });
    }

    // API 레이트 제한 방지
    if (i < allPosts.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 5000));
    }
  }

  // 결과 저장
  const logPath = path.join(process.env.HOME, '.blogger-posts-output', 'publishing-complete.json');
  fs.writeFileSync(logPath, JSON.stringify(results, null, 2));

  // 최종 보고
  console.log('\n═══════════════════════════════════════');
  console.log('📈 발행 완료');
  console.log('═══════════════════════════════════════');
  console.log(`✅ 성공: ${successCount}/${allPosts.length}`);
  console.log(`❌ 실패: ${errorCount}/${allPosts.length}`);
  console.log(`📋 로그: ${logPath}`);
}

publishAllPosts().catch(err => {
  console.error('❌ 발행 실패:', err);
  process.exit(1);
});
